UPDATE gif SET view_count = view_count + CASE id
WHEN #{gifId} THEN #{viewCount}
END, updated_at = NOW() WHERE id IN
#{gifId}
AND status = 1

UPDATE gif SET download_count = download_count + CASE id
WHEN #{gifId} THEN #{downloadCount}
END, updated_at = NOW() WHERE id IN
#{gifId}
AND status = 1

UPDATE gif SET like_count = like_count + CASE id
WHEN #{gifId} THEN #{likeCount}
END, updated_at = NOW() WHERE id IN
#{gifId}
AND status = 1
